class Solution {
  public int maxProfit(int n, int[][] edges, int[] score) {
    int[] pre = new int[n];
    for (int[] e : edges) pre[e[1]] |= 1 << e[0];
    int full = (1 << n) - 1;
    int[] dp = new int[full + 1];
    java.util.Arrays.fill(dp, -1);
    dp[0] = 0;
    for (int mask = 0; mask < full; mask++) {
      if (dp[mask] < 0) continue;
      int pos = Integer.bitCount(mask) + 1;
      for (int u = 0; u < n; u++) {
        if ((mask >> u & 1) != 0 || (pre[u] & mask) != pre[u]) continue;
        int nm = mask | 1 << u, v = dp[mask] + score[u] * pos;
        if (v > dp[nm]) dp[nm] = v;
      }
    }
    return dp[full];
  }
}
